const $=s=>document.querySelector(s);
const magazines=[
 {id:'10',date:'Aug – Oct 2019',year:'2019',title:'Feel good. Live well.',topic:'Movement, food & everyday wellbeing',tags:['Movement','Nutrition'],alt:'InVision Wellness Magazine, 10th edition. Two fitness professionals on the cover.'},
 {id:'07',date:'Nov 2018 – Jan 2019',year:'2018',title:'From trauma to triumph',topic:'King Salomon’s road to recovery',tags:['Resilience','Community'],alt:'InVision Wellness Magazine, 7th edition. King Salomon seated in his wheelchair against colourful street art.'},
 {id:'06',date:'Aug – Oct 2018',year:'2018',title:'A woman’s glow',topic:'Pregnancy, mental health & more',tags:['Pregnancy','Mind'],alt:'InVision Wellness Magazine, 6th edition. A pregnant woman in a white dress.'},
 {id:'04',date:'Feb – Apr 2018',year:'2018',title:'A little heart goes a long way',topic:'Relationships, family & financial wellness',tags:['Relationships','Family'],alt:'InVision Wellness Magazine, 4th edition. A heart made from a collage of people.'}
];
const testimonials=[
 {quote:'Many of the audiences truly enjoyed your presentations.',credit:'Leena',context:'World AIDS Day at the Bank of Namibia'},
 {quote:'They delivered the results of the health screens to the respective employees in a timely and confidential manner.',credit:'Raturua',context:'Corporate wellness services'},
 {quote:'Their work has been a major factor in the improvement of our staff Wellness programme.',credit:'Vilyo',context:'Staff wellness programme'},
 {quote:'Within 2 weeks of placing the advert in InVision Wellness Magazine, a major pharmaceutical sales company listed my product and bought all of my stock.',credit:'Pink Cup Sales Associate',context:'InVision Wellness Magazine advertiser'}
];
let quoteIndex=0,magFilter='All',magSearch='',breathTimer=null,breathStart=0,activeRoute='';
let saved=[];try{saved=JSON.parse(localStorage.getItem('invision-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}
const arrow='<span aria-hidden="true">↗</span>';
const button=(label,href,cls='dark')=>`<a class="button ${cls}" href="${href}">${label}${arrow}</a>`;
const heading=(eyebrow,title,description='')=>`<div class="page-head wrap reveal"><div class="crumb"><a href="#/">Home</a> / ${eyebrow}</div><span class="eyebrow">${eyebrow.toUpperCase()}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;
const inquiry=(type,label='Let’s talk')=>`<button class="button dark" data-inquiry="${type}">${label}${arrow}</button>`;
function magCard(m){return `<article class="mag-card"><div class="cover-wrap"><button class="mag-cover" data-mag="${m.id}" aria-label="Preview ${m.alt}"><img src="assets/magazine-${m.id}.jpg" alt="${m.alt}" loading="lazy" width="400" height="565"></button><button class="save-button ${saved.includes(m.id)?'saved':''}" data-save="${m.id}" aria-pressed="${saved.includes(m.id)}" aria-label="${saved.includes(m.id)?'Unsave':'Save'} edition ${m.id}">${saved.includes(m.id)?'♥':'♡'}</button></div><div class="mag-meta">Edition ${m.id} · ${m.date}</div><h3>${m.title}</h3><button class="text-link" data-mag="${m.id}">Explore the cover ↗</button></article>`}
function breath(){return `<section class="pause-section section wrap"><div><span class="eyebrow">A LITTLE SPACE FOR YOU</span><h2>Your next step?<br>Take a <em>breath.</em></h2><p>Before the next meeting. Before the next thing. Give yourself one quiet minute, right here.</p><p style="font-size:12px">Follow a gentle, comfortable rhythm. Breathe naturally whenever you prefer.</p></div><div class="breath-box"><div class="breath-orbit"><div class="breath-circle" id="breath-circle"><strong id="breath-label">Just be.</strong><span id="breath-count">YOUR ONE-MINUTE RESET</span></div></div><button class="button light" data-action="breathe" id="breath-button">Start my minute <span>↗</span></button><div class="breath-status" id="breath-status" role="status">A little pause can be a lovely place to start.</div></div></section>`}
function quotes(){const t=testimonials[quoteIndex];return `<div class="quote-mark" aria-hidden="true">“</div><blockquote class="quote" style="margin:0">${t.quote}</blockquote><div class="quote-credit"><div><strong>${t.credit}</strong><br><span style="color:var(--muted)">${t.context}</span></div><div class="quote-controls"><button class="circle-button" data-quote="-1" aria-label="Previous testimonial">←</button><button class="circle-button" data-quote="1" aria-label="Next testimonial">→</button></div></div>`}
function home(){return `<section class="hero wrap reveal"><div class="hero-copy"><span class="eyebrow"><span class="dot"></span>ROOTED IN NAMIBIA. MADE FOR REAL LIFE.</span><h1>For your body.<br>Your mind.<br>Your <em class="soul">soul.</em></h1><p>Wellness is a whole-life kind of thing. Let’s make space for more energy, better balance, and a little more you.</p><div class="hero-actions">${button('Find your feel-good','#/corporate','purple')}<a class="text-link" href="#/about">Get to know us ↗</a></div><div class="hero-foot">IF YOU CAN SEE IT, THEN YOU CAN BE IT.</div></div><div class="hero-art photo-hero"><div class="hero-photo-frame"><img id="hero-scene" src="assets/movement.png" alt="Illustrative lifestyle scene of three women enjoying an outdoor walk" width="1536" height="1024" fetchpriority="high"><div class="photo-bottom"><span id="hero-scene-caption">A LITTLE MORE MOVEMENT.</span><span>01 / 04</span></div></div><div class="eye-sticker"><img src="assets/eye-original.jpeg" alt="The original InVision multicoloured eye photograph"><span>A FRESH PERSPECTIVE</span></div><span class="photo-star" aria-hidden="true">✳</span><div class="scene-switcher" role="group" aria-label="Explore wellness imagery"><button class="active" data-scene="movement" aria-pressed="true"><img src="assets/movement.png" alt=""><span>Move</span></button><button data-scene="workplace" aria-pressed="false"><img src="assets/workplace.png" alt=""><span>Connect</span></button><button data-scene="nourish" aria-pressed="false"><img src="assets/nourish.png" alt=""><span>Nourish</span></button><button data-scene="bloom" aria-pressed="false"><img src="assets/bloom.png" alt=""><span>Grow</span></button></div><button class="floating-note" data-action="pause"><span class="note-top"><span class="note-icon">✷</span>A moment for yourself <span>↗</span></span><p>Try your one-minute breathing break.</p></button></div></section><div class="ticker" aria-label="Move a little. Learn something. Find your balance. Feel more you."><div class="ticker-track" aria-hidden="true">${Array(4).fill('<span>MOVE A LITTLE</span><b>✳</b><span>LEARN SOMETHING</span><b>✳</b><span>FIND YOUR BALANCE</span><b>✳</b><span>FEEL MORE YOU</span><b>✳</b>').join('')}</div></div><section class="section wrap"><div class="section-head"><div><span class="eyebrow">WELCOME TO OUR WORLD</span><h2>Wellness, with a<br>fresh <em>perspective.</em></h2></div><p>From the workplace to your everyday, we bring practical wellness closer to the people who need it. Good information. Real support. Room to grow.</p></div><div class="world-grid"><a class="world-card coral" href="#/corporate"><span class="card-no">01 / AT WORK</span><span class="round-arrow">↗</span><div class="card-art image-art"><img src="assets/workplace.png" alt="Illustrative workplace stretch break" loading="lazy"></div><h3>People first.<br>Better together.</h3><p>Corporate wellness programmes built around your team and their everyday lives.</p></a><a class="world-card lavender" href="#/magazine"><span class="card-no">02 / IN YOUR HANDS</span><span class="round-arrow">↗</span><div class="card-art"><img class="mini-book" src="assets/magazine-06.jpg" alt="" loading="lazy"><img class="mini-book" src="assets/magazine-10.jpg" alt="" loading="lazy"></div><h3>A good read.<br>A better outlook.</h3><p>Local voices and expert perspectives in InVision Wellness Magazine.</p></a><a class="world-card green" href="#/vault"><span class="card-no">03 / ON YOUR SCREEN</span><span class="round-arrow">↗</span><div class="card-art image-art"><img src="assets/nourish.png" alt="Colourful food and a moment to nourish" loading="lazy"><span class="image-art-label">VA(u)LT</span></div><h3>Small lessons.<br>Everyday possibility.</h3><p>Practical wellness learning, one short video at a time. Meet The VA(u)LT.</p></a></div><div class="mission-strip"><img src="assets/eye-original.jpeg" alt="" loading="lazy"><p>We see the whole person. That’s why our approach brings health, movement, education and behavioural wellbeing together.</p></div></section><section class="magazine-section"><div class="wrap section"><div class="section-head"><div><span class="eyebrow">THE MAGAZINE / FROM OUR ARCHIVE</span><h2>Local stories.<br><em>New ways to see.</em></h2></div><a class="text-link" href="#/magazine">Explore the magazine ↗</a></div><div class="magazine-grid">${magazines.map(magCard).join('')}</div><div class="mag-bottom"><p>A look back at the covers that started conversations. Preview the artwork and ask the team about issue availability.</p><a class="text-link" href="#/magazine">Read. Share. Be inspired. ↗</a></div></div></section>${breath()}<section class="section wrap"><div class="bloom-panel"><div class="bloom-art bloom-photo"><img class="bloom-lifestyle" src="assets/bloom.png" alt="Illustrative pregnancy wellness scene: a couple sharing a relaxed moment at home" loading="lazy"><img class="bloom-photo-logo" src="assets/bloom.svg" alt="BLOOM by InVision Wellness"></div><div class="bloom-copy"><span class="eyebrow">A NEW CHAPTER, TOGETHER</span><h2>A little more ready.<br>A lot more <em>supported.</em></h2><p>Meet BLOOM: our six-week, in-person pregnancy preparation course. Practical learning for pregnancy, birth and the weeks that follow — with space for your partner, too.</p><div class="pills"><span class="pill">6 weeks</span><span class="pill">In person</span><span class="pill">N$1,500 / participant</span></div>${button('Discover BLOOM','#/bloom')}</div></div></section><section class="section wrap testimonial-section"><div class="quote-layout"><div><span class="eyebrow">WORDS FROM OUR COMMUNITY</span><h2>Good things<br>happen with<br><em>good people.</em></h2></div><div id="quote-content" aria-live="polite">${quotes()}</div></div></section><section class="wrap" style="padding-bottom:85px"><div class="city-strip"><span class="city-icon" aria-hidden="true">✳</span><div><span class="eyebrow" style="margin-bottom:12px">OUT OF THE ORDINARY. INTO THE CITY.</span><h3>Wellness belongs out here.</h3><p>Be part of Wellness in the City — as an exhibitor or sponsor.</p></div>${button('Get involved','#/city')}</div></section><section class="closing wrap"><span class="eyebrow">YOUR NEXT CHAPTER STARTS WITH A CONVERSATION</span><h2>Let’s make room<br>for <em>feeling good.</em></h2>${button('Say hello','#/contact','purple')}</section>`}
function corporate(){return heading('Corporate wellness','A healthier team.<br>A stronger <em>everyday.</em>','Wellness works best when it fits the people behind the job titles. Build a programme around your team’s needs, interests and working lives.')+`<section class="wrap content-section two-col"><div><span class="eyebrow">PEOPLE BEFORE PROGRAMMES</span><h2>More than a<br>once-a-year talk.</h2><p>We pair education with practical activities and follow-through. From a focused wellness day to an ongoing programme, the starting point is understanding your workplace.</p><div class="service-list" style="margin-top:35px">${[['Health awareness & screening','Health talks and workplace screening, with confidential individual results and an overview to help guide future wellness activities. Discuss the appropriate scope with our team.'],['Movement & team connection','Group fitness, team-building activities, ergonomics discussions and practical ways to bring movement into the workday.'],['Everyday wellbeing','Nutrition, stress management, women’s and men’s health, HIV/AIDS workplace management and individual wellness coaching.'],['Learning that keeps going','Magazine content and The VA(u)LT can support your programme between sessions, making learning easier to share.']].map((s,i)=>`<div class="service-item"><span>0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div></div>`).join('')}</div></div><aside class="planner"><span class="eyebrow">LET’S FIND YOUR STARTING POINT</span><h3>Your team. Your plan.</h3><p>A few details to spark a useful conversation. This is a programme idea, ready for the team to tailor with you.</p><form id="planner-form"><div class="field"><label for="team-size">How big is your team?</label><select id="team-size"><option>Under 25 people</option><option>25–100 people</option><option>More than 100 people</option></select></div><div class="field"><label for="team-goal">What would you like to focus on?</label><select id="team-goal"><option value="balance">Stress & balance</option><option value="movement">Movement & connection</option><option value="awareness">Health awareness</option></select></div><button class="button dark" type="submit">Shape my starting point ${arrow}</button></form><div class="planner-result hidden" id="planner-result" role="status"></div></aside></section><section class="wrap" style="padding-bottom:80px"><div class="callout"><div><h3>Let’s build something that fits.</h3><p>Tell us what you have in mind and we’ll discuss programme options, scheduling and a tailored quotation.</p></div>${inquiry('Corporate wellness','Talk to the team')}</div></section>`}
function magazine(){return heading('The magazine','A good read.<br>A fresh <em>outlook.</em>','Namibian voices. Professional perspectives. Everyday wellness, from movement and nutrition to mental, family and financial wellbeing.')+`<section class="wrap content-section"><div class="section-head"><div><span class="eyebrow">THE COVER ARCHIVE</span><h2>Take a closer look.</h2></div><p>Explore four editions from our archive. Save a favourite to this browser or preview a cover in detail.</p></div><div class="filters" aria-label="Filter magazine covers">${['All','2019','2018','Saved'].map(x=>`<button class="filter ${magFilter===x?'active':''}" data-filter="${x}" aria-pressed="${magFilter===x}">${x==='All'?'All covers':x==='Saved'?'Saved ♡':x}</button>`).join('')}<input class="search" type="search" id="mag-search" aria-label="Search cover titles and topics" placeholder="Find a topic…" value="${escapeHtml(magSearch)}"></div><div class="magazine-grid" id="magazine-results">${filteredMagazines()}</div><p class="archive-note">Cover previews only. Full issue files are not currently available on this site. Ask us about print and digital availability.</p><div class="callout"><div><h3>There’s room for your story.</h3><p>Bring magazines to your business, connect with our readers as an advertiser, or contribute your professional perspective.</p></div>${inquiry('Magazine — distribution','Get involved')}</div><div class="facts"><div class="fact"><h3>For your business</h3><p>Make wellness reading part of your waiting area or employee wellness programme.</p><button class="text-link" style="margin-top:20px" data-inquiry="Magazine — distribution">Distribution enquiry ↗</button></div><div class="fact"><h3>For your brand</h3><p>Talk to us about advertising opportunities and sharing your offering with wellness-minded readers.</p><button class="text-link" style="margin-top:20px" data-inquiry="Magazine — advertising">Advertising enquiry ↗</button></div><div class="fact"><h3>For your expertise</h3><p>Health and wellness professionals help make reliable, relevant information more accessible.</p><button class="text-link" style="margin-top:20px" data-inquiry="Magazine — contributor">Become a contributor ↗</button></div></div></section>`}
function filteredMagazines(){const list=magazines.filter(m=>(magFilter==='All'||magFilter==='Saved'&&saved.includes(m.id)||m.year===magFilter)&&[m.title,m.topic,m.date,...m.tags].join(' ').toLowerCase().includes(magSearch.toLowerCase()));return list.length?list.map(magCard).join(''):'<p class="empty">No covers here yet. Try another topic, or save a cover using its heart button.</p>'}
function vault(){return heading('The VA(u)LT','A small lesson.<br>A new <em>possibility.</em>','Video-assisted unique learning tools. Short, practical wellness content created to bring learning into the working day.')+`<section class="wrap content-section"><div class="vault-feature"><div class="vault-symbol vault-photo"><img src="assets/nourish.png" alt="Fresh food, colour and everyday wellness" loading="lazy"><div class="vault-photo-brand"><div class="vault-mark">VA<span>(u)</span>LT</div><p>VIDEO-ASSISTED UNIQUE LEARNING TOOLS</p></div></div><div><span class="eyebrow">LEARN IT. TRY IT. LIVE IT.</span><h2>Expert perspectives.<br>Everyday application.</h2><p>The VA(u)LT brings 5–10 minute wellness videos together with supporting magazine content and practical behaviour-change tools. Designed for teams of different sizes, including those without a dedicated wellness officer.</p>${inquiry('The VA(u)LT — company interest','Explore a package')}</div></div><div class="facts"><div class="fact"><h3>Short by design</h3><p>Bite-sized learning that’s easier to make space for, with practical ideas to put into action.</p></div><div class="fact"><h3>Local perspectives</h3><p>Content featuring professionals in Namibia’s health, fitness, mental wellbeing and financial wellness fields.</p></div><div class="fact"><h3>Shared more easily</h3><p>Packages for small, medium and large enterprises, with content that can be shared by your designated staff member.</p></div></div><div class="callout"><div><h3>Have something worth sharing?</h3><p>We’d love to hear from professionals interested in contributing to The VA(u)LT. Video access and package details are available from the team.</p></div>${inquiry('The VA(u)LT — contributor','Become a contributor')}</div></section>${breath()}`}
const bloomTopics=[['Pregnancy, with perspective','Understand the clinical journey and the questions to bring to your care team, alongside practical learning about nutrition, movement and everyday wellbeing.'],['Preparing for birth','Use information and demonstrations to become more familiar with delivery and the transition into the postpartum period.'],['Your wellbeing matters, too','Make space for mental and emotional wellbeing during pregnancy and after birth, alongside physical preparation.'],['Practical skills for a new chapter','The course includes demonstrations, infant CPR learning and a closer look at healthy product choices.'],['Bring your partner into the picture','A partner masterclass creates space to learn together and talk about practical support during this new chapter.']];
function bloom(){return heading('BLOOM','Growing a family.<br>Growing <em>confidence.</em>','Pregnancy preparation with practical learning, thoughtful support and space to ask questions. Six weeks to feel a little more ready for what comes next.')+`<section class="wrap content-section"><div class="bloom-hero"><div class="bloom-course-photo"><img class="bloom-lifestyle" src="assets/bloom.png" alt="Illustrative pregnancy preparation scene" loading="lazy"><img class="bloom-photo-logo" src="assets/bloom.svg" alt="BLOOM by InVision Wellness"></div><div><span class="eyebrow">PREGNANCY · BIRTH · POSTPARTUM</span><h2>Your next chapter,<br>with support.</h2><div class="pills"><span class="pill">6-week course</span><span class="pill">Twice weekly</span><span class="pill">45-minute sessions</span><span class="pill">In person</span></div><div class="price">N$1,500 <span>per participant</span></div><p>Required exercise equipment included. Medical aid claims may be available; confirm eligibility and benefits with the team and your provider.</p>${inquiry('BLOOM — registration interest','Enquire about joining')}</div></div><div class="two-col"><div><span class="eyebrow">MAKE ROOM FOR THE QUESTIONS</span><h2>Information meets<br><em>demonstration.</em></h2><p>Learning what to expect is one part of preparation. Seeing and practising how is another. BLOOM brings both into the room, with a partner masterclass included in the programme.</p><p style="font-size:13px">Contact us for the next course dates, venue, availability and registration process.</p></div><div class="accordion">${bloomTopics.map((s,i)=>`<details ${i===0?'open':''}><summary>${s[0]}</summary><p>${s[1]}</p></details>`).join('')}</div></div></section>`}
function about(){return heading('Our story','A whole-person view.<br>A very human <em>approach.</em>','InVision Wellness brings health, education, fitness and behavioural wellbeing together to support healthier, happier and more productive lives in Namibia.')+`<section class="wrap content-section two-col"><div><span class="eyebrow">IF YOU CAN SEE IT, THEN YOU CAN BE IT.</span><h2>Seeing possibility.<br>Supporting change.</h2></div><div><p>We believe wellness education is most useful when people can put it into practice. Our approach pairs information with movement, coaching and practical support that fits real life.</p><p>Co-managed by Hileni Phillips and Deidre Kwenani, InVision Wellness draws on nursing, public health, social work and behavioural health expertise. Our multidisciplinary approach connects individual needs with the wider wellbeing of a workplace and community.</p><p>Our magazine, corporate programmes and learning tools offer different ways into the same conversation: what would a healthier life look like for you, and how can we help you move towards it?</p><div class="values"><span class="value">Integrity</span><span class="value">Professionalism</span><span class="value">Excellence</span><span class="value">Transparency</span></div></div></section><section class="wrap content-section"><div class="section-head"><div><span class="eyebrow">THE PEOPLE BEHIND THE PERSPECTIVE</span><h2>Meet Hileni & Deidre.</h2></div><p>Different disciplines. A shared commitment to supporting the whole person.</p></div><div class="team-grid"><article class="team-card"><span class="initial" aria-hidden="true">H.</span><span class="eyebrow">CO-MANAGEMENT</span><h3>Hileni Phillips</h3><p>Talk to Hileni about your individual or corporate wellness needs.</p><a class="text-link" href="tel:+264812910252">+264 81 291 0252 ↗</a></article><article class="team-card"><span class="initial" aria-hidden="true">D.</span><span class="eyebrow">CO-MANAGEMENT</span><h3>Deidre Kwenani</h3><p>Connect with Deidre and explore what wellness could look like for you.</p><a class="text-link" href="tel:+264812072700">+264 81 207 2700 ↗</a></article></div></section><section class="wrap section testimonial-section"><div class="quote-layout"><div><span class="eyebrow">OUR COMMUNITY</span><h2>In their <em>words.</em></h2></div><div id="quote-content" aria-live="polite">${quotes()}</div></div></section>`}
function city(){return heading('Wellness in the City','More connection.<br>More <em>good energy.</em>','Bring your wellness offering into the community. Express your interest in exhibiting at or sponsoring Wellness in the City.')+`<section class="wrap content-section"><div class="city-page-art"><img class="city-photo" src="assets/movement.png" alt="Illustrative outdoor movement and community scene" loading="lazy"><div><span class="eyebrow">LET’S BRING WELLNESS CLOSER</span><h2>Meet.<br>Move.<br><em>Connect.</em></h2><p>Interested in being part of the next event? Let’s start a conversation. Dates, venue and participation details will be shared by the team when confirmed.</p></div><span aria-hidden="true">✳</span></div><div class="facts" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))"><div class="fact"><h3>Bring your booth</h3><p>Introduce your business, products or wellness services to the community. Tell us what you would like to showcase.</p><div style="margin-top:25px">${inquiry('Wellness in the City — exhibitor','Exhibit with us')}</div></div><div class="fact"><h3>Support the experience</h3><p>Explore sponsorship and partnership opportunities that help make community wellness possible.</p><div style="margin-top:25px">${inquiry('Wellness in the City — sponsor','Become a sponsor')}</div></div></div></section>`}
function courses(){return heading('MyCourses','A little learning.<br>A lot of <em>possibility.</em>','Explore learning with InVision Wellness. Our current course offering is BLOOM, an in-person pregnancy preparation programme.')+`<section class="wrap content-section"><article class="course-card"><div class="course-art course-photo"><img src="assets/bloom.png" alt="Illustrative BLOOM pregnancy wellness scene" loading="lazy"></div><div class="course-body"><span class="eyebrow">IN-PERSON LEARNING</span><h2>BLOOM pregnancy preparation</h2><p>Six weeks. Two 45-minute sessions each week. Practical preparation for pregnancy, birth and postpartum.</p><div class="price">N$1,500 <span>per participant</span></div>${button('Explore the programme','#/bloom')}</div></article><div class="callout"><div><h3>Already learning with us?</h3><p>Online course sign-in, content access and checkout are being prepared. Contact the team for enrolment help and payment arrangements.</p></div>${inquiry('Course access & enrolment','Get course support')}</div></section>`}
const inquiryTypes=['General enquiry','Corporate wellness','Magazine — distribution','Magazine — advertising','Magazine — contributor','The VA(u)LT — company interest','The VA(u)LT — contributor','BLOOM — registration interest','Wellness in the City — exhibitor','Wellness in the City — sponsor','Course access & enrolment'];
function enquiryForm(type='General enquiry',modal=false){const p=modal?'modal-':'contact-';return `<form class="enquiry-form" data-prefix="${p}"><div class="form-row"><div class="field"><label for="${p}name">Your name *</label><input id="${p}name" name="name" required maxlength="100" autocomplete="name"></div><div class="field"><label for="${p}email">Email address *</label><input id="${p}email" name="email" type="email" required maxlength="150" autocomplete="email"></div></div><div class="field"><label for="${p}org">Business / organisation</label><input id="${p}org" name="organisation" maxlength="150" autocomplete="organization"></div><div class="field"><label for="${p}interest">I’m interested in *</label><select id="${p}interest" name="interest">${inquiryTypes.map(x=>`<option ${x===type?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="${p}message">What do you have in mind? *</label><textarea id="${p}message" name="message" required maxlength="2000" placeholder="Tell us a little about your enquiry…"></textarea></div><label class="consent"><input type="checkbox" required><span>I’m happy for InVision Wellness to use these details to respond to my enquiry.</span></label><p class="form-note">Please keep this to a general enquiry. For your privacy, do not include medical records, test results or sensitive health information.</p><button class="button dark" type="submit">Prepare my email ${arrow}</button><p class="form-note">This opens an email draft for you to review and send. Your enquiry is not submitted automatically.</p><div class="form-status" role="status"></div></form>`}
function contact(){return heading('Let’s connect','Good things start<br>with a <em>hello.</em>','A question, a partnership idea, or a programme for your team. We’d love to hear what you have in mind.')+`<section class="wrap content-section contact-grid"><div class="contact-details"><span class="eyebrow">WINDHOEK, NAMIBIA</span><h2>Let’s talk <em>wellness.</em></h2><a class="text-link" href="mailto:wellnessinvision@gmail.com">wellnessinvision@gmail.com ↗</a><div class="contact-person"><h3>Hileni Phillips</h3><a href="tel:+264812910252">+264 81 291 0252 ↗</a></div><div class="contact-person"><h3>Deidre Kwenani</h3><a href="tel:+264812072700">+264 81 207 2700 ↗</a></div><p style="font-size:13px;margin-top:35px">HD InVision Wellness Consultancy cc<br>P.O. Box 27023, Windhoek<br>Namibia</p></div><div class="contact-form">${enquiryForm()}</div></section>`}
const pages={'/':home,'/corporate':corporate,'/magazine':magazine,'/vault':vault,'/bloom':bloom,'/about':about,'/city':city,'/courses':courses,'/contact':contact};
const titles={'/':'Body, mind & soul','/corporate':'Corporate wellness','/magazine':'The magazine','/vault':'The VA(u)LT','/bloom':'BLOOM pregnancy preparation','/about':'Our story','/city':'Wellness in the City','/courses':'MyCourses','/contact':'Let’s connect'};
function render(){stopBreath(false);const route=location.hash.replace(/^#/,'')||'/';activeRoute=route;const page=pages[route];$('#main').innerHTML=page?page():heading('Page not found','Let’s find your way <em>back.</em>')+`<section class="wrap content-section">${button('Back to our world','#/')}</section>`;enhancePhotography(route);document.title=`${titles[route]||'Page not found'} | InVision Wellness`;document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.nav-drop').open=false;window.scrollTo(0,0);if($('#modal').open)$('#modal').close()}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showModal(content){$('#modal-content').innerHTML=content;$('#modal').showModal()}
function toast(msg){$('.toast').textContent=msg;$('.toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2600)}
function startBreath(){if(breathTimer){stopBreath();return}breathStart=Date.now();$('#breath-button').innerHTML='Finish my pause <span>×</span>';$('#breath-status').textContent='Follow along, or choose your own comfortable rhythm.';let lastPhase=-1;const update=()=>{const elapsed=(Date.now()-breathStart)/1000;if(elapsed>=60){stopBreath(false);$('#breath-label').textContent='Lovely.';$('#breath-count').textContent='ONE MINUTE, JUST FOR YOU';$('#breath-status').textContent='Take that little moment of space into your day.';return}const phase=Math.floor(elapsed/5)%2;if(phase!==lastPhase){lastPhase=phase;$('#breath-circle').classList.toggle('expand',phase===0);$('#breath-label').textContent=phase===0?'Breathe in.':'Breathe out.'}$('#breath-count').textContent=`${60-Math.floor(elapsed)} SECONDS OF SPACE`};update();breathTimer=setInterval(update,200)}
function stopBreath(update=true){if(breathTimer)clearInterval(breathTimer);breathTimer=null;$('#breath-circle')?.classList.remove('expand');if($('#breath-button'))$('#breath-button').innerHTML='Start my minute <span>↗</span>';if(update&&$('#breath-label')){$('#breath-label').textContent='Just be.';$('#breath-count').textContent='YOUR ONE-MINUTE RESET';$('#breath-status').textContent='Whenever you’re ready, start again.'}}
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-action]');if(!target)return;if(target.matches('.menu-toggle')){const open=$('nav').classList.toggle('open');target.setAttribute('aria-expanded',String(open));target.setAttribute('aria-label',open?'Close menu':'Open menu')}if(target.matches('.modal-close'))$('#modal').close();if(target.dataset.inquiry){showModal(`<span class="eyebrow">LET’S MAKE A CONNECTION</span><h2>${target.dataset.inquiry.startsWith('BLOOM')?'Let’s grow together.':'Tell us a little more.'}</h2>${enquiryForm(target.dataset.inquiry,true)}`)}if(target.dataset.mag){const m=magazines.find(x=>x.id===target.dataset.mag);showModal(`<span class="eyebrow">ARCHIVE · EDITION ${m.id} · ${m.date}</span><img class="modal-cover" src="assets/magazine-${m.id}.jpg" alt="${m.alt}"><h2>${m.title}</h2><p>${m.topic}</p><div class="modal-tags">${m.tags.map(x=>`<span class="pill">${x}</span>`).join('')}</div><p>This is a cover preview from our archive. Contact us for issue availability and reading options.</p>${inquiry('Magazine — distribution','Ask about this issue')}`)}if(target.dataset.save){const id=target.dataset.save;if(saved.includes(id))saved=saved.filter(x=>x!==id);else saved.push(id);try{localStorage.setItem('invision-saved',JSON.stringify(saved))}catch{toast('Browser storage unavailable. Saved for this visit.')}target.classList.toggle('saved',saved.includes(id));target.setAttribute('aria-pressed',String(saved.includes(id)));target.setAttribute('aria-label',`${saved.includes(id)?'Unsave':'Save'} edition ${id}`);target.textContent=saved.includes(id)?'♥':'♡';toast(saved.includes(id)?'Saved to your cover collection.':'Removed from your saved covers.');if(magFilter==='Saved'&&$('#magazine-results'))$('#magazine-results').innerHTML=filteredMagazines()}if(target.dataset.filter){magFilter=target.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===magFilter);b.setAttribute('aria-pressed',String(b.dataset.filter===magFilter))});$('#magazine-results').innerHTML=filteredMagazines()}if(target.dataset.quote){quoteIndex=(quoteIndex+Number(target.dataset.quote)+testimonials.length)%testimonials.length;$('#quote-content').innerHTML=quotes()}if(target.dataset.action==='pause'){const section=$('.pause-section');section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});$('#breath-button').focus({preventScroll:true})}if(target.dataset.action==='breathe')startBreath();if(target.dataset.action==='portal')showModal(`<span class="eyebrow">QUICK CARE CLINIC</span><h2>Patient portal<br>is being prepared.</h2><p>Secure sign-in, intake forms and test-result access are not active yet. The clinic is a future service.</p><p>Please do not send test results or medical records through the website’s general enquiry form.</p>${button('Contact the team','#/contact')}`);if(target.dataset.action==='privacy')showModal(`<span class="eyebrow">YOUR DETAILS, WITH CARE</span><h2>Privacy & enquiries.</h2><p>The enquiry form prepares an email on your device. Nothing is sent until you review and send it through your email app. This site does not store enquiry form responses.</p><p>Saved magazine covers are stored only in this browser. Use the heart buttons to remove them, or clear your browser’s site data.</p><p>We do not collect patient information or display medical records on this website. For questions about your details, contact wellnessinvision@gmail.com.</p><p>Typography may be loaded from Google Fonts. If it is unavailable, your device’s fonts are used.</p>`)});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
document.addEventListener('input',e=>{if(e.target.id==='mag-search'){magSearch=e.target.value;$('#magazine-results').innerHTML=filteredMagazines()}});
document.addEventListener('submit',e=>{if(e.target.id==='planner-form'){e.preventDefault();const goal=$('#team-goal').value,size=$('#team-size').value;const plans={balance:['Make space for balance',['A facilitated stress-awareness conversation','A practical break or gentle group movement session','Follow-up learning through magazine content or The VA(u)LT']],movement:['Bring the team together',['A group fitness or team-building session','A discussion about ergonomics and everyday movement','A simple follow-up activity plan for your workplace']],awareness:['Start with awareness',['A conversation about your team’s health priorities','Discuss appropriate workplace screening with our professionals','A health education session and next-step guidance']]};const p=plans[goal];$('#planner-result').innerHTML=`<span class="eyebrow">A STARTING POINT · ${size.toUpperCase()}</span><h4>${p[0]}</h4><ul>${p[1].map(x=>`<li>${x}</li>`).join('')}</ul><p>We’ll confirm the scope, availability and cost with you.</p>${inquiry('Corporate wellness','Discuss this idea')}`;$('#planner-result').classList.remove('hidden')}
if(e.target.matches('.enquiry-form')){e.preventDefault();const form=e.target,data=new FormData(form);const subject=`Website enquiry: ${data.get('interest')}`;const body=`Hello InVision Wellness,\n\n${data.get('message')}\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\nOrganisation: ${data.get('organisation')||'Not supplied'}\nInterest: ${data.get('interest')}\n\nI consent to being contacted about this enquiry.`;const url=`mailto:wellnessinvision@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;const status=form.querySelector('.form-status');status.innerHTML='<strong>Your email draft is ready.</strong><p>Open it in your email app, review your message, then send.</p>';const link=document.createElement('a');link.className='button purple';link.href=url;link.textContent='Open my email draft ↗';status.appendChild(link);const copy=document.createElement('button');copy.type='button';copy.className='text-link';copy.style.marginLeft='15px';copy.textContent='Copy enquiry';copy.onclick=async()=>{try{await navigator.clipboard.writeText(`To: wellnessinvision@gmail.com\nSubject: ${subject}\n\n${body}`);toast('Enquiry copied. Paste it into your email app.')}catch{const text=document.createElement('textarea');text.value=`To: wellnessinvision@gmail.com\nSubject: ${subject}\n\n${body}`;text.readOnly=true;status.appendChild(text);text.select();toast('Select and copy your enquiry below.')}};status.appendChild(copy);link.focus()}});
document.addEventListener('click',e=>{if(!e.target.closest('.nav-drop'))$('.nav-drop').open=false});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&breathTimer)stopBreath()});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()});

const scenes={movement:{caption:'A LITTLE MORE MOVEMENT.',alt:'Illustrative lifestyle scene of three women enjoying an outdoor walk',number:'01'},workplace:{caption:'GOOD ENERGY. GREAT COMPANY.',alt:'Illustrative scene of colleagues enjoying a workplace stretch break',number:'02'},nourish:{caption:'COLOUR ON YOUR PLATE. JOY IN YOUR DAY.',alt:'Colourful bowls of fresh food on a sunny table',number:'03'},bloom:{caption:'GROWING, TOGETHER.',alt:'Illustrative scene of a pregnant woman and her partner at home',number:'04'}};
function enhancePhotography(route){const art={'/corporate':['workplace','WELLNESS THAT MOVES WITH YOUR PEOPLE.'],'/about':['movement','A WHOLE LIFE. A FRESH PERSPECTIVE.'],'/contact':['nourish','LET’S PUT SOMETHING GOOD INTO MOTION.']};if(!art[route])return;const [src,caption]=art[route];const banner=document.createElement('figure');banner.className='page-photo-band wrap';banner.innerHTML='<div><img src="assets/'+src+'.png" alt="Illustrative wellness lifestyle image" loading="lazy"><figcaption>'+caption+'</figcaption></div>';document.querySelector('.page-head').after(banner)}
document.addEventListener('click',e=>{const scene=e.target.closest('[data-scene]');if(scene){const key=scene.dataset.scene,s=scenes[key],image=$('#hero-scene');image.src='assets/'+key+'.png';image.alt=s.alt;$('#hero-scene-caption').textContent=s.caption;document.querySelector('.photo-bottom span:last-child').textContent=s.number+' / 04';document.querySelectorAll('[data-scene]').forEach(b=>{b.classList.toggle('active',b.dataset.scene===key);b.setAttribute('aria-pressed',String(b.dataset.scene===key))})}if(e.target.closest('[data-action="image-credit"]'))showModal('<span class="eyebrow">THE PICTURES</span><h2>A little creative perspective.</h2><p>The eye photograph and magazine covers were supplied by InVision. The eye photograph is reproduced unchanged.</p><p>The movement, workplace, pregnancy and food scenes were created with AI for this website. They are illustrative lifestyle imagery, rather than photographs of InVision staff, clients or events.</p>')});

window.addEventListener('hashchange',()=>{render();$('.menu-toggle').setAttribute('aria-label','Open menu')});$('#year').textContent=new Date().getFullYear();render();
